// utils/hyphenateLabel.ts

import de from 'hyphenation.de';
import Hypher from 'hypher';

const hypher = new Hypher(de);
const SOFT_HYPHEN = '\u00AD'; // Standard, funktioniert auf iOS

export function hyphenateLabel(text: string, minWordLength = 12) {
    const safe = String(text ?? '');

    return safe
        .split(/(\s+)/)
        .map((part) => {
        if (/^\s+$/.test(part)) return part;
        if (part.length < minWordLength) return part;

        // sonst normal trennen
        return hypher.hyphenate(part).join(SOFT_HYPHEN);
        })
        .join('');
}