// app/screens/Home/StreakScreen.tsx
import { useTheme } from "@/app/context/ThemeContext";
import {
  dynamicSpacing,
  getContentMaxWidth,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import { Colors } from "@/constants/theme";
import { Ionicons } from "@expo/vector-icons";
import { ScrollView, StyleSheet, Text, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

const GREY_BG = "#d1d1d1";
const GREY_BORDER = "#a0a0a0";
const GREY_TEXT = "#5f5f5f";

export default function StreakScreen() {
  const { mode } = useTheme();
  const themeColors = Colors[mode];
  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(700);

  // HARD-CODED DEMO VALUES
  const goalDays = 5 as number;
  const selectedMinutes = 10;
  const reminderEnabled = true;
  const reminderTimeText = "18:00";

  return (
    <SafeAreaView
      style={{
        flex: 1,
        backgroundColor: isWide ? "#f8f8f8" : themeColors.background,
        alignItems: isWide ? "center" : undefined,
      }}
    >
      <View
        style={[
          { flex: 1, width: "100%" },
          isWide && {
            maxWidth: contentMaxWidth,
            borderRadius: 16,
            backgroundColor: themeColors.background,
          },
        ]}
      >
        <ScrollView
          contentContainerStyle={[
            styles.container,
            {
              paddingBottom: isWide
                ? dynamicSpacing(40, 60)
                : dynamicSpacing(24, 30),
            },
          ]}
          showsVerticalScrollIndicator={false}
        >
          <View
            style={[
              styles.lockBanner,
              {
                backgroundColor: themeColors.card,
                borderColor: themeColors.border,
              },
            ]}
          >
            <Ionicons name="lock-closed" size={16} color={themeColors.text} />
            <Text style={[styles.lockBannerText, { color: themeColors.text }]}>
              Nur in der Vollversion verfügbar
            </Text>
          </View>

          {/* Wochenziel */}
          <View
            style={[
              styles.section,
              { width: isWide ? "70%" : isTablet ? "80%" : "85%" },
            ]}
          >
            <Text style={[styles.introText, { color: themeColors.text }]}>
              Wie viele Lerntage planst du pro Woche ein?
            </Text>

            <View style={styles.sliderRow}>
              <Text style={[styles.sliderLimit, { color: GREY_TEXT }]}>1</Text>

              <View style={styles.fakeSliderTrack}>
                <View style={styles.fakeSliderFill} />
                <View style={styles.fakeSliderThumb} />
              </View>

              <Text style={[styles.sliderLimit, { color: GREY_TEXT }]}>7</Text>
            </View>

            <Text style={[styles.sliderLabel, { color: GREY_TEXT }]}>
              {goalDays} {goalDays === 1 ? "Tag" : "Tage"} pro Woche
            </Text>
          </View>

          <View
            style={[styles.divider, { backgroundColor: themeColors.border }]}
          />

          {/* Tägliche Lernzeit */}
          <View
            style={[
              styles.section,
              { width: isWide ? "70%" : isTablet ? "80%" : "85%" },
            ]}
          >
            <Text style={[styles.introText, { color: themeColors.text }]}>
              Wie lange möchtest du pro Tag lernen?
            </Text>

            <View style={styles.timeGoalRow}>
              {["5", "10", "15", "30"].map((min) => {
                const isSelected = Number(min) === selectedMinutes;
                return (
                  <View
                    key={min}
                    style={[
                      styles.timeGoalButton,
                      {
                        borderColor: GREY_BORDER,
                        backgroundColor: GREY_BG,
                        opacity: isSelected ? 0.95 : 0.8,
                      },
                    ]}
                  >
                    <Text style={[styles.timeGoalText, { color: GREY_TEXT }]}>
                      {min} Min
                    </Text>
                  </View>
                );
              })}
            </View>

            <Text style={[styles.selectedMinutesText, { color: GREY_TEXT }]}>
              Aktuell: {selectedMinutes} Min
            </Text>
          </View>

          <View
            style={[styles.divider, { backgroundColor: themeColors.border }]}
          />

          {/* Erinnerung */}
          <View
            style={[
              styles.section,
              { width: isWide ? "70%" : isTablet ? "80%" : "85%" },
            ]}
          >
            <View style={styles.row}>
              <Text style={[styles.subTitle, { color: GREY_TEXT }]}>
                Erinnerung aktivieren
              </Text>

              <View style={styles.fakeSwitchTrack}>
                <View
                  style={[
                    styles.fakeSwitchThumb,
                    reminderEnabled && styles.fakeSwitchThumbOn,
                  ]}
                />
              </View>
            </View>

            {reminderEnabled && (
              <View style={styles.timeRow}>
                <Text style={[styles.timeLabel, { color: GREY_TEXT }]}>
                  Uhrzeit:
                </Text>
                <Text style={[styles.timeText, { color: GREY_TEXT }]}>
                  {reminderTimeText}
                </Text>
              </View>
            )}
          </View>

          <View
            style={[
              styles.saveButton,
              { backgroundColor: GREY_BG, borderColor: GREY_BORDER },
              { width: isWide ? "70%" : isTablet ? "80%" : "85%" },
            ]}
          >
            <Text style={[styles.saveButtonText, { color: GREY_TEXT }]}>
              Ziel speichern
            </Text>
          </View>
        </ScrollView>
      </View>
    </SafeAreaView>
  );
}

