// ExamresultScreen.tsx

import { useTheme } from "@/app/context/ThemeContext";
import {
  dynamicIconSize,
  dynamicSpacing,
  getContentMaxWidth,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import { useNavigation, useRoute } from "@react-navigation/native";
import LottieView from "lottie-react-native";
import { useEffect } from "react";
import {
  BackHandler,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { markLearningDayWeb, saveExamResultWeb } from "../utils/userResultsWeb";

export default function ExamResultScreen() {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const {
    score = 0,
    maxScore = 0,
    duration = 0,
    answersJSON = "{}",
    examId = null,
  } = route.params || {};

  const { theme } = useTheme() as any; // <-- NEU
  const isDarkMode = theme.dark === true; // <-- NEU
  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(isTablet ? 700 : 520);

  const percent = maxScore > 0 ? Math.round((score / maxScore) * 100) : 0;

  useEffect(() => {
    navigation.setOptions({
      headerShown: false,
      gestureEnabled: false, // verhindert Wischen-zurück auf iOS
    });
  }, [navigation]);

  useEffect(() => {
    const backHandler = BackHandler.addEventListener(
      "hardwareBackPress",
      () => {
        return true; // verhindert, dass Android zurück navigiert
      },
    );
    return () => backHandler.remove();
  }, []);

  useEffect(() => {
    (async () => {
      try {
        const parsedAnswers = JSON.parse(answersJSON || "[]");
        await saveExamResultWeb(score, maxScore, parsedAnswers);
        await markLearningDayWeb();
      } catch (err) {
        console.error("Fehler beim Speichern des Prüfungsergebnisses:", err);
      }
    })();
  }, []);

  const handleBack = () => {
    navigation.reset({
      index: 0,
      routes: [{ name: "HomeTabs" }],
    });
  };

  return (
    <SafeAreaView
      style={{
        flex: 1,
        backgroundColor: isDarkMode ? theme.colors.background : "#34495e",
      }}
    >
      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        <View
          style={[
            styles.contentWrapper,
            isWide && { maxWidth: contentMaxWidth },
            { alignSelf: "center" },
          ]}
        >
          <LottieView
            source={require("../../assets/animations/Exam_end.json")}
            autoPlay
            loop={false}
            style={styles.animation}
          />

          <Text
            style={[styles.points, isDarkMode && { color: theme.colors.text }]}
          >
            {score} / {maxScore} Punkte ({percent}%)
          </Text>

          <Text
            style={[
              styles.duration,
              isDarkMode && { color: theme.colors.text },
            ]}
          >
            🕒 {Math.round(duration / 60)} min
          </Text>

          <TouchableOpacity style={styles.button} onPress={handleBack}>
            <Text style={styles.buttonText}>Zurück</Text>
          </TouchableOpacity>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: "#34495e",
    justifyContent: "center",
    alignItems: "center",
    paddingHorizontal: dynamicSpacing(20, 40),
  },
  scrollContent: {
    flexGrow: 1,
    alignItems: "center",
    justifyContent: "center",
    paddingVertical: dynamicSpacing(10, 14),
  },

  contentWrapper: {
    width: "100%",
    alignItems: "center",
    justifyContent: "center",
    paddingHorizontal: dynamicSpacing(14, 20),
  },

  animation: {
    width: dynamicIconSize(260, 420),
    height: dynamicIconSize(260, 420),
    marginBottom: dynamicSpacing(20, 30),
  },
  points: {
    fontSize: scaleFont(22),
    fontFamily: "Montserrat-Bold",
    color: "#ffffff",
    marginBottom: dynamicSpacing(6, 10),
  },
  duration: {
    fontSize: scaleFont(16),
    fontFamily: "Montserrat-Regular",
    color: "#d9d9d9",
    marginBottom: dynamicSpacing(30, 40),
  },
  button: {
    backgroundColor: "#e8630a",
    borderRadius: 10,
    paddingVertical: dynamicSpacing(14, 18),
    paddingHorizontal: dynamicSpacing(40, 56),
  },
  buttonText: {
    fontSize: scaleFont(18),
    fontFamily: "Montserrat-Bold",
    color: "#fff",
  },
});
