// app/Training/OutroScreen.tsx
import { useTheme } from "@/app/context/ThemeContext";
import {
  dynamicSpacing,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import {
  CommonActions,
  useNavigation,
  useRoute,
} from "@react-navigation/native";

import LottieView from "lottie-react-native";
import { useEffect } from "react";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { markLearningDayWeb, saveUserResultWeb } from "../utils/userResultsWeb";

export default function OutroScreen() {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();

  const { theme } = useTheme();

  const { subchapterId, chapterId, chapterTitle, points, maxPoints, origin } =
    route.params || {};

  const pointsNum = Number(points) || 0;
  const maxPointsNum = Number(maxPoints) || 0;
  const percent =
    maxPointsNum > 0 ? Math.round((pointsNum / maxPointsNum) * 100) : 0;
  const { width } = useOrientation();
  const isWide = width >= 768;

  let animationSource;
  let resultText;

  if (percent <= 30) {
    animationSource = require("@/assets/animations/bad_points.json");
    resultText = "Da ist noch Luft nach oben. Versuch’s gleich nochmal!";
  } else if (percent <= 69) {
    animationSource = require("@/assets/animations/low_points.json");
    resultText = "Ganz ordentlicher Versuch, aber da geht noch was.";
  } else if (percent <= 89) {
    animationSource = require("@/assets/animations/medium_points.json");
    resultText = "Saubere Arbeit, das Kapitel sitzt schon ziemlich sicher.";
  } else {
    animationSource = require("@/assets/animations/top_points.json");
    resultText = "Mega! Du hast das Thema wirklich drauf!";
  }

  const handleBack = () => {
    if (route.params?.origin === "progress") {
      navigation.dispatch(
        CommonActions.reset({
          index: 0,
          routes: [{ name: "HomeTabs", params: { screen: "Fortschritt" } }],
        }),
      );
      return;
    }

    navigation.dispatch(
      CommonActions.reset({
        index: 1,
        routes: [
          { name: "HomeTabs" },
          {
            name: "Training",
            state: {
              index: 1,
              routes: [
                { name: "Chapters" },
                { name: "Subchapters", params: { chapterId, chapterTitle } },
              ],
            },
          },
        ],
      }),
    );
  };

  useEffect(() => {
    (async () => {
      if (subchapterId) {
        await saveUserResultWeb(
          Number(subchapterId),
          "training",
          pointsNum,
          maxPointsNum,
        );
        await markLearningDayWeb();
      }
    })();
  }, [subchapterId, pointsNum, maxPointsNum]);

  return (
    <View
      style={[
        styles.container,
        {
          backgroundColor: theme.colors.background,
          alignItems: "center",
          paddingHorizontal: dynamicSpacing(20, 30),
          paddingVertical: dynamicSpacing(40, 60),
          justifyContent: "center", // ← HIER
        },
      ]}
    >
      <View
        style={{
          width: dynamicSpacing(250, 280),
          height: dynamicSpacing(250, 280),
          marginBottom: dynamicSpacing(20, 24),
        }}
      >
        <LottieView
          source={animationSource}
          autoPlay
          loop={false}
          style={{ width: "100%", height: "100%" }}
        />
      </View>

      <Text
        style={[
          styles.subtitle,
          {
            color: theme.colors.text,
            width: isWide ? "80%" : "90%",
            marginTop: dynamicSpacing(10, 16),
            marginBottom: dynamicSpacing(10, 16),
          },
        ]}
      >
        {resultText}
      </Text>

      <TouchableOpacity
        style={[styles.button, { marginTop: dynamicSpacing(36, 44) }]}
        onPress={handleBack}
      >
        <Text style={styles.buttonText}>Fertig</Text>
      </TouchableOpacity>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
    paddingHorizontal: dynamicSpacing(20, 40),
  },
  animation: {
    alignSelf: "center",
  },
  title: {
    fontSize: scaleFont(20),
    fontFamily: "Montserrat-Bold",
    marginTop: dynamicSpacing(20, 28),
  },
  points: {
    fontSize: scaleFont(18),
    fontFamily: "Montserrat-Bold",
    marginTop: dynamicSpacing(10, 16),
  },
  subtitle: {
    fontSize: scaleFont(16),
    fontFamily: "Montserrat-Regular",
    textAlign: "center",
    width: "100%", // ← WICHTIG
    maxWidth: 420, // ← optional, aber sauber
  },

  button: {
    backgroundColor: "#e8630a",
    paddingVertical: dynamicSpacing(14, 18),
    paddingHorizontal: dynamicSpacing(24, 36),
    borderRadius: isTablet ? 10 : 8,
    marginTop: dynamicSpacing(30, 40),
  },
  buttonText: {
    color: "white",
    fontSize: scaleFont(18),
    fontFamily: "Montserrat-Regular",
  },
});
