// utils/responsive.ts
import { Dimensions, PixelRatio, useWindowDimensions } from "react-native";

const BASE_WIDTH = 375; // Referenz: iPhone 11
const SCALE_CAP_WIDTH = 430; // Skalierung nie breiter als ein großes Phone
const TABLET_BREAKPOINT = 768; // echte Tablet-Breite

// Achtung: raw = echte Fensterbreite (Chromebook!), capped = nur für Skalierung
const { width: rawW, height: rawH } = Dimensions.get("window");

export const rawWidth = rawW;
export const rawHeight = rawH;

// Nur fürs Scaling deckeln (damit Chromebook nicht alles riesig macht)
export const cappedWidth = Math.min(rawW, SCALE_CAP_WIDTH);

// Device-Klassen bitte auf rawWidth basieren (nicht capped!)
export const isSmallScreen = rawW < 360;
export const isMediumScreen = rawW >= 360 && rawW < TABLET_BREAKPOINT;
export const isTablet = rawW >= TABLET_BREAKPOINT;

// Fonts skalieren (nur mit cappedWidth)
export const scaleFont = (size: number): number => {
  const scale = cappedWidth / BASE_WIDTH;
  const newSize = size * scale;
  return Math.round(PixelRatio.roundToNearestPixel(newSize));
};

// Spacing/Icons nicht „tablet = groß“, sondern mit rawWidth entscheiden:
export const dynamicSpacing = (small: number, large: number): number => {
  return cappedWidth >= TABLET_BREAKPOINT ? large : small;
};

export const dynamicIconSize = (small: number, large: number): number => {
  return cappedWidth >= TABLET_BREAKPOINT ? large : small;
};

// Orientierung + raw sizes (für Screens)
export const useOrientation = () => {
  const { width, height } = useWindowDimensions();
  return {
    width,
    height,
    isLandscape: width > height,
    isPortrait: height >= width,
  };
};

// Für Chromebook/Tablet: Content-Breite begrenzen (App bleibt "hochformat")
export const getContentMaxWidth = (defaultMax = 520) => {
  return defaultMax;
};
