// app/screens/Training/ContentSlide.tsx

import { useTheme } from "@/app/context/ThemeContext";
import { getImageByKey } from "@/app/utils/imageMappings";

import {
  dynamicIconSize,
  dynamicSpacing,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";

import { Image, ScrollView, StyleSheet, Text } from "react-native";

interface ContentSlideProps {
  title: string;
  text: string;
  image?: string;
  onNext: () => void;
}

export default function ContentSlide({
  text,
  image,
  title,
  onNext,
}: ContentSlideProps) {
  const { theme } = useTheme();
  const key = image
    ? image.replace(/\.(png|jpe?g|webp)$/i, "").replace(/^.*[\\/]/, "")
    : null;
  const imageSource = key ? getImageByKey(key) : null;
  const { width, height } = useOrientation();
  const isWide = width >= 768;
  const maxImageHeight = Math.min(height * 0.35, 240);

  return (
    <ScrollView
      contentContainerStyle={[
        styles.container,
        {
          backgroundColor: theme.colors.background,
          flexGrow: 1,
          paddingTop: isWide ? dynamicSpacing(20, 30) : dynamicSpacing(40, 60),
        },
      ]}
      showsVerticalScrollIndicator={false}
    >
      <Text style={[styles.title, { color: theme.colors.text }]}>{title}</Text>
      {imageSource ? (
        <Image
          source={imageSource}
          style={[
            styles.image,
            {
              width: isWide ? "55%" : "85%",
              height: undefined,
              aspectRatio: 1.5,
              maxHeight: maxImageHeight,
              marginTop: isWide
                ? dynamicSpacing(20, 30)
                : dynamicSpacing(50, 60),
              marginBottom: isWide
                ? dynamicSpacing(30, 40)
                : dynamicSpacing(50, 70),
            },
          ]}
          resizeMode="contain"
        />
      ) : null}

      <Text
        style={[
          styles.text,
          {
            color: theme.colors.text,
            marginBottom: isWide
              ? dynamicSpacing(20, 30)
              : dynamicSpacing(40, 60),
          },
        ]}
      >
        {text}
      </Text>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: "flex-start",
    alignItems: "center",
    paddingHorizontal: dynamicSpacing(20, 30),
    paddingTop: dynamicSpacing(40, 60),
  },
  title: {
    fontFamily: "Lato-Bold",
    fontSize: scaleFont(22),
    marginBottom: dynamicSpacing(20, 28),
    textAlign: "center",
  },
  image: {
    width: "80%",
    height: dynamicIconSize(220, 300),
    marginTop: dynamicSpacing(50, 60),
    marginBottom: dynamicSpacing(50, 70),
  },
  text: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(18),
    textAlign: "center",
    marginBottom: dynamicSpacing(40, 60),
  },
});
